<?php
use DigiForge\POD\PrintifyWebhookInbox;
use DigiForge\POD\PrintifyWebhookRequest;
require_once __DIR__.'/fixtures/PortalAccessFixture.php';
require_once __DIR__.'/fixtures/PrintifyWebhookConfigFixture.php';
final class PrintifyWebhookInboxTest extends WP_UnitTestCase {
 private static string $path;
 private string $oldHome; private string $oldSite;
 private string $binding='c123456789abcdef0123456789abcdef';
 public static function set_up_before_class():void{parent::set_up_before_class();self::$path=PrintifyWebhookConfigFixture::path();}
 protected function setUp():void{parent::setUp();if(DIGIFORGE_PRINTIFY_WEBHOOK_CONFIG!==self::$path)$this->markTestSkipped('Private webhook config already provisioned.');$this->oldHome=get_option('home');$this->oldSite=get_option('siteurl');update_option('home','https://isolated.invalid');update_option('siteurl','https://isolated.invalid');$this->config();}
 protected function tearDown():void{global $wpdb;$wpdb->query('ROLLBACK');$wpdb->query('SET autocommit=1');update_option('home',$this->oldHome);update_option('siteurl',$this->oldSite);$wpdb->query("DELETE FROM {$wpdb->options} WHERE option_name LIKE 'digiforge_pfy_hook_%'");$wpdb->delete(\DigiForge\Database\Tables::audit_log(),['object_type'=>'printify_webhook']);$wpdb->query('START TRANSACTION');parent::tearDown();}
 public static function tear_down_after_class():void{parent::tear_down_after_class();}
 private function config(array $extra=[]):void{file_put_contents(self::$path,json_encode([$this->binding=>$extra+['site'=>home_url(),'shop_key'=>'personalized_pod','integration_id'=>123,'provider_shop_id'=>'123','current_secret'=>str_repeat('a',32)]]));chmod(self::$path,0600);}
 private function raw(string $shop='123'):string{return json_encode(['id'=>'12345678-1234-1234-1234-123456789abc','type'=>'order:created','created_at'=>gmdate('Y-m-d H:i:s+00:00'),'resource'=>['id'=>'order123','type'=>'order','data'=>['shop_id'=>$shop,'address'=>'PRIVATE_NOT_PERSISTED']]]);}
 private function receive(string $raw,string $key=''):array|WP_Error{return PrintifyWebhookInbox::receive($this->binding,$raw,'sha256='.hash_hmac('sha256',$raw,$key?:str_repeat('a',32)));}
 public function testLifecycleBodiesAndSigningFingerprint():void{$create=PrintifyWebhookRequest::prepare('WEBHOOK_CREATE','123',['binding'=>$this->binding,'topic'=>'order:created']);self::assertSame(hash('sha256',str_repeat('a',32)),$create['secret_fingerprint']);self::assertSame('order:created',$create['body']['topic']);self::assertArrayNotHasKey('secret',$create['body']);$update=PrintifyWebhookRequest::prepare('WEBHOOK_UPDATE','123',['binding'=>$this->binding,'topic'=>'order:created','webhook_id'=>'hook123']);self::assertSame(['url'=>rest_url('digiforge/v1/printify/webhooks/ingress/'.$this->binding)],$update['body']);self::assertArrayNotHasKey('secret_fingerprint',$update);$this->config(['current_secret'=>str_repeat('c',32)]);$rotated=PrintifyWebhookRequest::prepare('WEBHOOK_CREATE','123',['binding'=>$this->binding,'topic'=>'order:created']);self::assertNotSame($create['secret_fingerprint'],$rotated['secret_fingerprint']);}
 public function testUnsignedAdministratorCannotReconcileReceipt():void{global $wpdb;$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');$raw=$this->raw();self::assertIsArray($this->receive($raw));$event=PrintifyWebhookInbox::authenticate($this->binding,$raw,'sha256='.hash_hmac('sha256',$raw,str_repeat('a',32)));$actor=self::factory()->user->create(['role'=>'administrator']);get_userdata($actor)->add_cap('manage_digiforge_connections');wp_set_current_user($actor);$result=PrintifyWebhookInbox::reconcile($event['dedupe_key'],'RETRY_LOCAL',0,'manual review');self::assertWPError($result);self::assertSame(403,$result->get_error_data()['status']);self::assertNull($wpdb->get_var($wpdb->prepare("SELECT option_value FROM {$wpdb->options} WHERE option_name=%s",'digiforge_pfy_hook_state_'.$event['dedupe_key'])));}
 public function testMissingAuditAnchorBlocksDuplicateAndReconciliation():void{global $wpdb;$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');$raw=$this->raw();self::assertIsArray($this->receive($raw));$event=PrintifyWebhookInbox::authenticate($this->binding,$raw,'sha256='.hash_hmac('sha256',$raw,str_repeat('a',32)));$wpdb->delete(\DigiForge\Database\Tables::audit_log(),['event_type'=>'printify_webhook_received','object_id'=>$event['dedupe_key']]);self::assertWPError($this->receive($raw));$r=PrintifyWebhookInbox::reconcile($event['dedupe_key'],'RETRY_LOCAL',0,'manual review');self::assertWPError($r);self::assertSame('digiforge_printify_webhook_corrupt_receipt',$r->get_error_code());}
 public function testThirdLocalRetryIsDeadLetterWithoutScheduling():void{global $wpdb;PortalAccessFixture::reset();PortalAccessFixture::enroll();$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');$raw=$this->raw();self::assertIsArray($this->receive($raw));$event=PrintifyWebhookInbox::authenticate($this->binding,$raw,'sha256='.hash_hmac('sha256',$raw,str_repeat('a',32)));try{for($revision=0;$revision<3;$revision++){$r=PrintifyWebhookInbox::reconcile($event['dedupe_key'],'RETRY_LOCAL',$revision,'manual review');self::assertIsArray($r);self::assertFalse($r['scheduled']);self::assertFalse($r['business_transition_authorized']);}self::assertSame(3,$r['attempts']);self::assertSame('DEAD_LETTER',$r['state']);}finally{PortalAccessFixture::reset();}}
 public function testInvalidSignatureDoesNotPersist():void{global $wpdb;$r=$this->receive($this->raw(),str_repeat('b',32));self::assertWPError($r);self::assertSame('0',(string)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->options} WHERE option_name LIKE 'digiforge_pfy_hook_%'"));}
 public function testOuterTransactionRejected():void{$r=$this->receive($this->raw());self::assertWPError($r);self::assertSame('digiforge_printify_webhook_transaction_active',$r->get_error_code());}
 public function testReceiptAndAuditAreDurableAndDuplicateDoesNotWrite():void{global $wpdb;$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');$raw=$this->raw();$r=$this->receive($raw);self::assertIsArray($r);$again=$this->receive($raw);self::assertSame('DUPLICATE_NO_TRANSITION',$again['state']);$conflict=$this->receive(str_replace('order123','order456',$raw));self::assertWPError($conflict);self::assertSame(409,$conflict->get_error_data()['status']);$stored=$wpdb->get_var("SELECT option_value FROM {$wpdb->options} WHERE option_name LIKE 'digiforge_pfy_hook_%' LIMIT 1");self::assertStringNotContainsString('PRIVATE_NOT_PERSISTED',$stored);$table=\DigiForge\Database\Tables::audit_log();self::assertSame('1',(string)$wpdb->get_var("SELECT COUNT(*) FROM $table WHERE event_type='printify_webhook_received'"));}
 public function testRotationBoundedAndCrossShopRejected():void{$this->config(['previous_secret'=>str_repeat('b',32),'rotation_started_at'=>time()-60,'previous_valid_until'=>time()+60]);self::assertIsArray(PrintifyWebhookInbox::authenticate($this->binding,$raw=$this->raw(),'sha256='.hash_hmac('sha256',$raw,str_repeat('b',32))));self::assertWPError($this->receive($this->raw('999')));$this->config(['previous_secret'=>str_repeat('b',32),'rotation_started_at'=>time()-120,'previous_valid_until'=>time()-1]);self::assertWPError(PrintifyWebhookInbox::authenticate($this->binding,$raw,'sha256='.hash_hmac('sha256',$raw,str_repeat('b',32))));}
 public function testAuditFailureRollsBackReceipt():void{global $wpdb;$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');$table=\DigiForge\Database\Tables::audit_log();$filter=static function($query)use($table){return str_starts_with($query,"INSERT INTO `$table`")?'INSERT INTO intentionally_missing_webhook_audit_table VALUES (1)':$query;};add_filter('query',$filter);$wpdb->suppress_errors(true);try{$r=$this->receive($this->raw());self::assertWPError($r);}finally{remove_filter('query',$filter);$wpdb->suppress_errors(false);}self::assertSame('0',(string)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->options} WHERE option_name LIKE 'digiforge_pfy_hook_%'"));}
}
